PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS audit_events; DROP TABLE IF EXISTS lineage_edges; DROP TABLE IF EXISTS connector_settings; DROP TABLE IF EXISTS data_sources; DROP TABLE IF EXISTS export_jobs; DROP TABLE IF EXISTS dashboard_shares; DROP TABLE IF EXISTS dashboard_charts; DROP TABLE IF EXISTS dashboards; DROP TABLE IF EXISTS calculated_columns; DROP TABLE IF EXISTS charts; DROP TABLE IF EXISTS dataset_rows; DROP TABLE IF EXISTS dataset_columns; DROP TABLE IF EXISTS ingestion_jobs; DROP TABLE IF EXISTS datasets; DROP TABLE IF EXISTS workspace_members; DROP TABLE IF EXISTS workspaces; DROP TABLE IF EXISTS reset_tokens; DROP TABLE IF EXISTS sessions; DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,global_role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE reset_tokens(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE workspaces(id INTEGER PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,quota_rows INTEGER NOT NULL DEFAULT 10000,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE workspace_members(workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',PRIMARY KEY(workspace_id,user_id));
CREATE TABLE datasets(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id),owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'ready',row_count INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(workspace_id,name));
CREATE TABLE ingestion_jobs(id INTEGER PRIMARY KEY,dataset_id INTEGER UNIQUE NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,status TEXT NOT NULL,error_message TEXT,created_at TEXT NOT NULL,finished_at TEXT);
CREATE TABLE dataset_columns(id INTEGER PRIMARY KEY,dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,name TEXT NOT NULL,data_type TEXT NOT NULL,position INTEGER NOT NULL,UNIQUE(dataset_id,name));
CREATE TABLE dataset_rows(id INTEGER PRIMARY KEY,dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,row_index INTEGER NOT NULL,data TEXT NOT NULL,UNIQUE(dataset_id,row_index));
CREATE TABLE charts(id INTEGER PRIMARY KEY,dataset_id INTEGER NOT NULL REFERENCES datasets(id),owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,chart_type TEXT NOT NULL,dimension TEXT NOT NULL,measure TEXT NOT NULL,aggregation TEXT NOT NULL,filters TEXT NOT NULL DEFAULT '[]',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE calculated_columns(id INTEGER PRIMARY KEY,dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,name TEXT NOT NULL,expression TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(dataset_id,name));
CREATE TABLE dashboards(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id),owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE dashboard_charts(dashboard_id INTEGER NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,chart_id INTEGER NOT NULL REFERENCES charts(id) ON DELETE CASCADE,position INTEGER NOT NULL,PRIMARY KEY(dashboard_id,chart_id));
CREATE TABLE dashboard_shares(id INTEGER PRIMARY KEY,dashboard_id INTEGER NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),permission TEXT NOT NULL,UNIQUE(dashboard_id,user_id));
CREATE TABLE export_jobs(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),resource_type TEXT NOT NULL,resource_id INTEGER NOT NULL,format TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE data_sources(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id),owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,type TEXT NOT NULL,host TEXT NOT NULL,database_name TEXT NOT NULL,username TEXT NOT NULL,secret_hash TEXT NOT NULL,secret_mask TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'untested',version INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,name));
CREATE TABLE connector_settings(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE lineage_edges(id INTEGER PRIMARY KEY,dataset_id INTEGER NOT NULL REFERENCES datasets(id),target_type TEXT NOT NULL,target_id INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
